20	function TaskColumnHeader({
21	  label,
22	  color,
23	  count,
24	}: {
25	  label: string;
26	  color: string;
27	  count: number;
28	}) {
29	  return (
30	    <div className="flex min-w-0 flex-1 items-center justify-between border-r border-border bg-surface-secondary px-3 py-2.5 last:border-r-0">
31	      <div className="flex min-w-0 items-center gap-2">
32	        <div
33	          className="h-2 w-2 rounded-sm"
34	          style={{ background: color }}
35	          aria-hidden="true"
36	        />
37	        <span className="truncate text-xs font-semibold uppercase tracking-wide text-text-secondary">
38	          {label}
39	        </span>
40	      </div>
41	      <span
42	        className="rounded px-1.5 py-0.5 text-xs font-semibold"
43	        style={{ color, background: `${color}18` }}
44	      >
45	        {count}
46	      </span>
47	    </div>
48	  );
49	}
50	
51	function EmptyState({ message }: { message: string }) {
52	  return (
